import{_ as d,o as e,c as o,a2 as a}from"./chunks/framework.DGk0zlJw.js";const g=JSON.parse('{"title":"B-803 MVP 端到端走查（任务书 §成功标准）","description":"","frontmatter":{},"headers":[],"relativePath":"zh/acceptance-B803-e2e-walkthrough.md","filePath":"zh/acceptance-B803-e2e-walkthrough.md"}'),r={name:"zh/acceptance-B803-e2e-walkthrough.md"};function c(l,t,n,i,s,h){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="b-803-mvp-端到端走查-任务书-§成功标准" tabindex="-1">B-803 MVP 端到端走查（任务书 §成功标准） <a class="header-anchor" href="#b-803-mvp-端到端走查-任务书-§成功标准" aria-label="Permalink to &quot;B-803 MVP 端到端走查（任务书 §成功标准）&quot;">​</a></h1><blockquote><p>依赖：B-801..802、B-805 全部代码级完成（CI 绿）后，在<strong>一台 Windows 机器</strong>上执行。 成功标准（任务书 §MVP）：开机自启 → 桌面角落一直看到状态 → 一键 Run/Retry 成功，全程<strong>不开浏览器不登 GitHub</strong>。 铁律细项见 <a href="./acceptance-B705-L0-behavior.html">acceptance-B705-L0-behavior.md</a>（真机手动清单 5 项在 B-803 内逐条勾选）。 产出：录屏/截图归档 + 发现问题修复或开 Issue；B-804 需在此之上补一台<strong>干净 Win11 VM</strong>。</p></blockquote><h2 id="_0-准备-5-分钟" tabindex="-1">0. 准备（5 分钟） <a class="header-anchor" href="#_0-准备-5-分钟" aria-label="Permalink to &quot;0. 准备（5 分钟）&quot;">​</a></h2><ul><li>[ ] 下载 <code>beacon-nightly-windows-x86_64-setup.exe</code>（或便携 zip），校验 SHA256SUMS</li><li>[ ] 开始录屏（全程不间断；问题点单独截图）</li><li>[ ] 一台有 GitHub 仓库权限的机器 + 一个 PAT（用于连接录入与 Retry）</li><li>[ ] 备好一个可控的 workflow（可手动失败→重跑，如仓库内测试 workflow）</li></ul><h2 id="_1-脚本主链-任务书成功标准逐环" tabindex="-1">1. 脚本主链（任务书成功标准逐环） <a class="header-anchor" href="#_1-脚本主链-任务书成功标准逐环" aria-label="Permalink to &quot;1. 脚本主链（任务书成功标准逐环）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>步骤</th><th>操作</th><th>通过标准</th><th>结果</th></tr></thead><tbody><tr><td>1</td><td>安装/解压</td><td>跑 setup.exe（或解压 zip）</td><td>无报错；开始菜单出现 Beacon（zip 方式直接见到 <code>Beacon.App.exe</code> 图标）</td><td>☐</td></tr><tr><td>2</td><td>首启反馈</td><td>启动 Beacon</td><td>启动通知气泡 + 托盘图标 + 右下角状态胶囊；<strong>无主窗口、不进任务栏/Alt-Tab</strong></td><td>☐</td></tr><tr><td>3</td><td>开机自启</td><td>检查 <code>HKCU\\Software\\Microsoft\\Windows\\CurrentVersion\\Run</code></td><td>有 Beacon 项指向安装路径（设置里可关）</td><td>☐</td></tr><tr><td>4</td><td>录入连接</td><td>托盘菜单 → 设置 → 连接 → 类型 github → 填 Id + Token</td><td>「✓ 已保存」；测试连接返回 Healthy</td><td>☐</td></tr><tr><td>5</td><td><strong>token 红线</strong></td><td>打开 <code>%AppData%\\Beacon\\connections.json</code> 全文搜索 PAT 本体</td><td><strong>搜不到明文 token</strong>，只有 <code>credentialRef</code></td><td>☐</td></tr><tr><td>6</td><td>添加组件</td><td>设置 → 组件：<code>github.actions.runs</code> + <code>github.pull_requests</code>（选连接、必填字段）</td><td>列表出现两条；L2 面板出现对应行与计数</td><td>☐</td></tr><tr><td>7</td><td>钉桌面</td><td>组件行「钉」开关打开</td><td>L0 出现 tile（状态灯 + 标签）</td><td>☐</td></tr><tr><td>8</td><td>制造失败</td><td>让可控 workflow 失败一次</td><td>胶囊变红/计数变化 + 托盘着色 + <strong>Toast 弹出</strong>（按规则带声音）</td><td>☐</td></tr><tr><td>9</td><td>下钻详情</td><td>点 Toast（或 L2 行）进 L3</td><td>详情窗显示状态/仓库/阶段/错误摘要；不打断 L0</td><td>☐</td></tr><tr><td>10</td><td><strong>一键 Retry</strong></td><td>L3 点 [Retry]（全程不开浏览器）</td><td>workflow 重跑成功 → Success Toast + 灯变绿</td><td>☐</td></tr><tr><td>11</td><td>设置即时性</td><td>改级别色 / 动效档 / 透明度 / 胶囊开关</td><td>即刻生效（主题重启生效属预期）；重启后仍生效</td><td>☐</td></tr><tr><td>12</td><td>导入导出</td><td>设置 → 导出配置；改乱后导入</td><td>行为复原；导出文件无 token；提示重录密钥</td><td>☐</td></tr><tr><td>13</td><td>断网降级</td><td>断网</td><td>tile 灰空心灯 + Last update；无异常弹窗；恢复自动复位</td><td>☐</td></tr></tbody></table><h2 id="_2-四层交互清单-rfc-§6" tabindex="-1">2. 四层交互清单（RFC §6） <a class="header-anchor" href="#_2-四层交互清单-rfc-§6" aria-label="Permalink to &quot;2. 四层交互清单（RFC §6）&quot;">​</a></h2><ul><li>[ ] L0 tile 单击 → L2 打开并聚焦；ESC 关；失焦自动关</li><li>[ ] L2 行单击 → L3 详情；L3 关闭回到 L0 常驻</li><li>[ ] L0 悬停/拖动/收起-展开不激活窗口、不打断当前输入焦点</li><li>[ ] 托盘菜单全部入口可用（面板/设置/通知/刷新/退出）；热键 <code>Ctrl+Alt+B</code> 呼出面板</li><li>[ ] B-705 铁律真机手动清单 5 项全部勾选（见该文档）</li></ul><h2 id="_3-glm-额度端到端-验收反馈阻断级-连源→加组件→板上出真实数字" tabindex="-1">3. GLM 额度端到端（验收反馈阻断级：连源→加组件→板上出真实数字） <a class="header-anchor" href="#_3-glm-额度端到端-验收反馈阻断级-连源→加组件→板上出真实数字" aria-label="Permalink to &quot;3. GLM 额度端到端（验收反馈阻断级：连源→加组件→板上出真实数字）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>步骤</th><th>操作</th><th>通过标准</th><th>结果</th></tr></thead><tbody><tr><td>G1</td><td>录入 GLM 连接</td><td>设置 → 连接 → 类型 <code>bigmodel</code> → Id + PAT（或裸 Key）</td><td>测试连接返回 Healthy；提示「在下方组件向导选该连接，或用『一键添加』即可上板」</td><td>☐</td></tr><tr><td>G2</td><td>一键示例</td><td>设置 → bigmodel 模块 →「一键添加 GLM 额度组件（示例）」</td><td>组件列表出现 <code>bigmodel.usage:GLM</code>；Pinned=true 自动钉选；右下角 L0 胶囊出现 <strong>数值卡 + 进度条</strong></td><td>☐</td></tr><tr><td>G3</td><td>首数出屏</td><td>等待 ≤10s（CI/Ci 档）</td><td>胶囊显示「GLM 额度 · 已用 XX% · 剩 YY tokens · MM-DD HH:MM 重置」；进度条按已用%填充；右键 L2 行可见 <code>Source: GLM</code> 标注</td><td>☐</td></tr><tr><td>G4</td><td>字段映射自验</td><td>设置 → 组件 <code>bigmodel.usage:GLM</code> → 编辑 → 确认 <code>total_path/used_path/reset_path</code> 映射正确</td><td>字段路径与 GLM <code>quota/limit</code> 响应结构一致（<code>$.data.total</code> / <code>$.data.used</code> / <code>$.data.reset_at</code>）</td><td>☐</td></tr><tr><td>G5</td><td>手动强刷</td><td>托盘菜单 → Refresh All</td><td>数值/进度条实时刷新；日志 <code>%APPDATA%\\Beacon\\logs\\beacon-*.log</code> 有逐跳行（一键添加→拉取→字段映射→渲染）</td><td>☐</td></tr></tbody></table><blockquote><p>⚠️ <strong>截图必须在 Windows 真机产出</strong>（Linux 仅能跑单测/构建，WinUI 3 无法在此环境运行）。请在完成上述 G1–G5 后，对 L0 胶囊与 L2 面板各截一张，存入 <code>docs/img/</code> 并在 PR/回复中附上。</p></blockquote><h2 id="_4-归档" tabindex="-1">4. 归档 <a class="header-anchor" href="#_4-归档" aria-label="Permalink to &quot;4. 归档&quot;">​</a></h2><ul><li>[ ] 录屏/截图存 <code>docs/img/</code>（大录屏可放 Release 附件，README 链接）</li><li>[ ] 每个不通过项：当场修复（走门禁推送）或开 Issue</li><li>[ ] B-804：同一脚本在<strong>干净 Win11 VM</strong> 复跑一遍（下载→运行→本清单），记录 VC++/SmartScreen 等首装环境表现</li></ul>',13)])])}const b=d(r,[["render",c]]);export{g as __pageData,b as default};
